import{_ as a,o as e,c as i,ag as t}from"./chunks/framework.BwSLX4ak.js";const k=JSON.parse('{"title":"Server startup notices","description":"","frontmatter":{},"headers":[],"relativePath":"en/shitbot/startup-notices.md","filePath":"en/shitbot/startup-notices.md"}'),n={name:"en/shitbot/startup-notices.md"};function r(o,s,l,p,h,c){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="server-startup-notices" tabindex="-1">Server startup notices <a class="header-anchor" href="#server-startup-notices" aria-label="Permalink to &quot;Server startup notices&quot;">​</a></h1><p>Administrators can announce this instance&#39;s startup or have a proxy wait for a specific backend. Notices go only to groups explicitly listed in <code>onebot.allowed-group-ids</code>. Setting <code>allow-all-groups: true</code> does not expand the notice audience.</p><h2 id="announce-proxy-startup" tabindex="-1">Announce proxy startup <a class="header-anchor" href="#announce-proxy-startup" aria-label="Permalink to &quot;Announce proxy startup&quot;">​</a></h2><p>In BungeeCord or Velocity&#39;s <code>config.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">onebot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allowed-group-ids</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123456789</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  notices</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    server-startup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      target-server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      check-interval-seconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span></code></pre></div><p>Leave <code>target-server</code> empty. A notice is sent once the ShitBot runtime is ready and OneBot connects. Spigot standalone and Nukkit-MOT use this configuration too, with notification work handed back to the platform thread. Spigot backends neither connect to OneBot nor send notices themselves.</p><h2 id="wait-for-a-specific-backend" tabindex="-1">Wait for a specific backend <a class="header-anchor" href="#wait-for-a-specific-backend" aria-label="Permalink to &quot;Wait for a specific backend&quot;">​</a></h2><p>Configure this only on BungeeCord/Velocity:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">onebot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  notices</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    server-startup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      target-server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;survival&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      check-interval-seconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span></code></pre></div><p><code>survival</code> must be a backend name in the proxy configuration. Every 5 seconds, the proxy attempts a Minecraft status ping. The first valid response stops polling and triggers the notice. The backend may already be online or start later. An unknown backend is reported in the log. Spigot and Nukkit reject nonempty <code>target-server</code> values.</p><p>Here, “online” means the backend answers a status ping. It does not guarantee that every plugin, world pregeneration task, or application initialization has finished. This is one notice per proxy startup; later backend restarts do not trigger it again.</p><h2 id="notice-text-and-reloads" tabindex="-1">Notice text and reloads <a class="header-anchor" href="#notice-text-and-reloads" aria-label="Permalink to &quot;Notice text and reloads&quot;">​</a></h2><p>Edit the active language file, <code>lang/&lt;language&gt;.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">notices</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  server-startup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Server %server% has started. You can join now!&quot;</span></span></code></pre></div><p><code>%server%</code> is the target backend name or current platform name. <code>%platform%</code> is the platform running ShitBot.</p><p><code>/shitbot reload</code> does not resend a completed notice. If the target is still offline, the new configuration starts waiting again. If the notice was triggered while OneBot was disconnected, or some groups failed, pending state and the list of successful groups carry over to the new runtime. Unconfirmed groups are retried after reconnection. A network interruption can make the send result uncertain, so retries may duplicate notices; strict exactly-once delivery across network failures is not guaranteed. State exists only within the current plugin process. A normal restart begins a new startup notice cycle.</p>`,16)])])}const g=a(n,[["render",r]]);export{k as __pageData,g as default};
